class Solution:
    def findMaximumNumber(self, k: int, x: int) -> int:
        def acc(num):
            total, p = 0, x
            while (1 << p) <= num:
                blk = 1 << (p + 1)
                total += ((num + 1) // blk) << p
                r = (num + 1) % blk
                if r > (1 << p):
                    total += r - (1 << p)
                p += x
            return total
        lo, hi = 1, 1 << 58
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if acc(mid) <= k:
                lo = mid
            else:
                hi = mid - 1
        return lo

