class Solution {
public:
    long long findMaximumNumber(long long k, int x) {
        auto acc = [&](long long num) {
            long long total = 0;
            for (long long p = x; (1LL << p) <= num; p += x) {
                long long blk = 1LL << (p + 1);
                total += ((num + 1) / blk) << p;
                long long r = (num + 1) % blk;
                if (r > (1LL << p)) total += r - (1LL << p);
            }
            return total;
        };
        long long lo = 1, hi = 1LL << 58;
        while (lo < hi) {
            long long mid = lo + (hi - lo + 1) / 2;
            if (acc(mid) <= k) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
};

