var findMaximumNumber = function(k, x) {
    const acc = (num) => {
        let total = 0n;
        num = BigInt(num);
        for (let p = BigInt(x); (1n << p) <= num; p += BigInt(x)) {
            const blk = 1n << (p + 1n);
            total += ((num + 1n) / blk) << p;
            const r = (num + 1n) % blk;
            if (r > (1n << p)) total += r - (1n << p);
        }
        return total;
    };
    let lo = 1n, hi = 1n << 58n;
    const K = BigInt(k);
    while (lo < hi) {
        const mid = (lo + hi + 1n) / 2n;
        if (acc(mid) <= K) lo = mid;
        else hi = mid - 1n;
    }
    return Number(lo);
};
